class Solution {
public:
    int maxKDivisibleComponents(int n, vector<vector<int>>& edges, vector<int>& values, int k) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<long long> sum(n, 0);
        vector<int> parent(n, -1);
        vector<int> order;
        order.reserve(n);
        vector<bool> visited(n, false);
        order.push_back(0);
        visited[0] = true;
        for (int i = 0; i < n; i++) {
            int u = order[i];
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    parent[v] = u;
                    order.push_back(v);
                }
            }
        }
        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            sum[u] += values[u];
            if (sum[u] % k == 0) {
                ans++;
            } else {
                sum[parent[u]] += sum[u];
            }
        }
        return ans;
    }
};
